 // INSERT CODE HERE\n        {\n            grabber.setPosition(1.0);\n        }\n        // 2. ELSE IF GAMEPAD1.B IS PRESSED, SET SERVO TO 0.0\n        // INSERT CODE HERE\n        {\n            grabber.setPosition(0.0);\n        }\n        // 3. ELSE, SET SERVO TO 0.5\n        // INSERT CODE HERE\n        {\n            grabber.setPosition(0.5);\n        }\n    }\n}\n    '.trim(),showMotorVisual:!1,showDistanceSensor:!1,showColorSensor:!1},"comparison-operators":{code:'\npackage org.firstinspires.ftc.teamcode.opmodes;\n\nimport com.qualcomm.robotcore.eventloop.opmode.OpMode;\nimport com.qualcomm.robotcore.eventloop.opmode.TeleOp;\nimport com.qualcomm.robotcore.hardware.DcMotor;\nimport com.qualcomm.robotcore.hardware.DistanceSensor;\nimport org.firstinspires.ftc.robotcore.external.navigation.DistanceUnit;\n\n@TeleOp(name="Wall_Safety_Challenge")\npublic class WallSafety extends OpMode {\n\n    private DcMotor driveMotor;\n    private DistanceSensor distanceSensor;\n\n    @Override\n    public void init() {\n        driveMotor     = hardwareMap.get(DcMotor.class, "drive");\n        distanceSensor = hardwareMap.get(DistanceSensor.class, "front_sensor");\n    }\n\n    @Override\n    public void loop() {\n        double dist = distanceSensor.getDistance(DistanceUnit.CM);\n\n        // IF THE DISTANCE IS LESS THAN 10.0 cm\n        // INSERT CODE HERE\n        {\n            // COMMAND THE DRIVE MOTOR TO STOP\n            // INSERT CODE HERE\n        }\n        else {\n            driveMotor.setPower(-1 * gamepad1.left_stick_y);\n        }\n    }\n}\n    '.trim(),showMotorVisual:!0,showDistanceSensor:!0,showColorSensor:!1},"logical-operators":{code:'\npackage org.firstinspires.ftc.teamcode.opmodes;\n\nimport com.qualcomm.robotcore.eventloop.opmode.OpMode;\nimport com.qualcomm.robotcore.eventloop.opmode.TeleOp;\nimport com.qualcomm.robotcore.hardware.DcMotor;\n\n@TeleOp(name="Trigger_Safety_Challenge")\npublic class TriggerSafety extends OpMode {\n\n    private DcMotor drive;\n\n    @Override\n    public void init() {\n        drive = hardwareMap.get(DcMotor.class, "drive");\n    }\n\n    @Override\n    public void loop() {\n        // IF (NOT gamepad1.start) AND (gamepad1.left_trigger > 0.5)\n        // INSERT CODE HERE\n        {\n            telemetry.addLine("Drive System Active");\n            drive.setPower(-1 * gamepad1.left_stick_y);\n        }\n        else {\n            drive.setPower(0.0);\n        }\n    }\n}\n    '.trim(),showMotorVisual:!0,showDistanceSensor:!1,showColorSensor:!1},"intake-logic-challenge":{code:'\npackage org.firstinspires.ftc.teamcode.opmodes;\n\nimport com.qualcomm.robotcore.eventloop.opmode.OpMode;\nimport com.qualcomm.robotcore.eventloop.opmode.TeleOp;\nimport com.qualcomm.robotcore.hardware.ColorSensor;\nimport com.qualcomm.robotcore.hardware.DcMotor;\nimport com.qualcomm.robotcore.hardware.DistanceSensor;\nimport org.firstinspires.ftc.robotcore.external.navigation.DistanceUnit;\n\n@TeleOp(name="Safe_Intake_Practice")\npublic class SafeIntakePractice extends OpMode {\n\n    private DcMotor intake;\n    private ColorSensor color;\n    private DistanceSensor distance;\n\n    @Override\n    public void init() {\n        intake = hardwareMap.get(DcMotor.class, "intake");\n        color = hardwareMap.get(ColorSensor.class, "intake_color");\n        distance = hardwareMap.get(DistanceSensor.class, "intake_distance");\n    }\n\n    @Override\n    public void loop() {\n        double dist = distance.getDistance(DistanceUnit.CM);\n        int redValue = color.red();\n        int blueValue = color.blue();\n        boolean collect = gamepad1.a || gamepad1.right_trigger > 0.10;\n\n        // 1. IF dist < 5.0, STOP THE INTAKE\n        // 2. ELSE IF RED IS > 200 AND > BLUE, EJECT AT -1.0\n        // 3. ELSE IF collect, USE right_trigger AS POWER\n        // 4. ELSE, STOP EXPLICITLY AT 0.0\n        // INSERT THE COMPLETE IF / ELSE-IF / ELSE CHAIN\n\n        telemetry.addData("Distance", dist);\n        telemetry.addData("Red", redValue);\n        telemetry.addData("Blue", blueValue);\n    }\n}\n    '.trim(),showMotorVisual:!0,showDistanceSensor:!0,showColorSensor:!0}};function c({lesson:e}){const n=a[e],o=new URLSearchParams({code:n.code,lesson:e,showMotorVisual:String(n.showMotorVisual),showDistanceSensor:String(n.showDistanceSensor),showColorSensor:String(n.showColorSensor)}),c=`${(0,r.Ay)("/simulator/unit5.html")}?${o.toString()}`,l="Telemark Unit 5 Simulator";return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(i.A,{src:c,width:"100%",height:"1180px",iframeStyle:{border:"none"},title:l}),(0,s.jsxs)(t.A,{type:"info",title:l,children:[(0,s.jsx)("div",{children:"Supports gamepad-driven `if`, `else if`, and `else` logic with live branch visualization."}),(0,s.jsx)("div",{children:"Includes truth-table and condition-inspector views, plus mock distance and color sensor inputs when needed."}),(0,s.jsx)("div",{children:"Best for practicing decision logic, thresholds, and simple actuator commands."})]})]})}}}]);